import pandas as pd
import numpy as np

# Load data
crime_df = pd.read_csv('chunks_csv/moran_local_2023_crime.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Step 1: Handle missing values
crime_df = crime_df.dropna(subset=['Crime_value'])
data_points_used = len(crime_df)
print(f"data_points_used = {data_points_used}")

# Step 2: Define thresholds (using median)
crime_median = crime_df['Crime_value'].median()
high_crime_threshold = crime_median

# Step 3: Assess neighborhood crime rates
borough_neighbor_avg = {}
for borough in crime_df['borough']:
    neighbors = adjacency_df[adjacency_df['borough'] == borough]['neighbor']
    neighbor_crime = crime_df[crime_df['borough'].isin(neighbors)]['Crime_value']
    if len(neighbor_crime) > 0:
        borough_neighbor_avg[borough] = neighbor_crime.mean()
    else:
        borough_neighbor_avg[borough] = np.nan  # No neighbors

# Step 4 & 5: Identify HH and LL boroughs
hh_boroughs = []
ll_boroughs = []

for borough in crime_df['borough']:
    borough_crime = crime_df[crime_df['borough'] == borough]['Crime_value'].values[0]
    neighbor_avg = borough_neighbor_avg[borough]

    if not np.isnan(neighbor_avg):
        if borough_crime > high_crime_threshold and neighbor_avg > high_crime_threshold:
            hh_boroughs.append((borough, borough_crime, neighbor_avg))
        elif borough_crime < high_crime_threshold and neighbor_avg < high_crime_threshold:
            ll_boroughs.append((borough, borough_crime, neighbor_avg))

# Step 6: Statistical significance (permutation test with 500 shuffles)
def permutation_test(observed, n_permutations=500):
    boroughs = crime_df['borough'].values
    crime_values = crime_df['Crime_value'].values
    count_extreme = 0

    for _ in range(n_permutations):
        shuffled_values = np.random.permutation(crime_values)
        shuffled_df = pd.DataFrame({'borough': boroughs, 'Crime_value': shuffled_values})

        # Recompute neighbor averages
        shuffled_neighbor_avg = {}
        for b in boroughs:
            neighbors = adjacency_df[adjacency_df['borough'] == b]['neighbor']
            neighbor_crime = shuffled_df[shuffled_df['borough'].isin(neighbors)]['Crime_value']
            if len(neighbor_crime) > 0:
                shuffled_neighbor_avg[b] = neighbor_crime.mean()
            else:
                shuffled_neighbor_avg[b] = np.nan

        # Count how often shuffled data meets HH/LL criteria
        for b in boroughs:
            b_crime = shuffled_df[shuffled_df['borough'] == b]['Crime_value'].values[0]
            b_neighbor_avg = shuffled_neighbor_avg.get(b, np.nan)
            if not np.isnan(b_neighbor_avg):
                if (b_crime > high_crime_threshold and b_neighbor_avg > high_crime_threshold) or \
                   (b_crime < high_crime_threshold and b_neighbor_avg < high_crime_threshold):
                    count_extreme += 1

    p_value = count_extreme / (n_permutations * len(boroughs))
    return p_value

# Filter HH/LL boroughs for significance (p < 0.05)
significant_hh = []
significant_ll = []

for borough, b_crime, n_avg in hh_boroughs:
    p_value = permutation_test((b_crime, n_avg))
    if p_value < 0.05:
        significant_hh.append((borough, b_crime, n_avg, p_value))

for borough, b_crime, n_avg in ll_boroughs:
    p_value = permutation_test((b_crime, n_avg))
    if p_value < 0.05:
        significant_ll.append((borough, b_crime, n_avg, p_value))

# Prepare final answer
final_answer = []
for borough, b_crime, n_avg, p_value in significant_hh:
    final_answer.append(f"{borough} (HH, p_value={p_value:.4f})")

for borough, b_crime, n_avg, p_value in significant_ll:
    final_answer.append(f"{borough} (LL, p_value={p_value:.4f})")

if not final_answer:
    print("FINAL ANSWER: none")
else:
    print("FINAL ANSWER: " + ", ".join(final_answer))
